import {
	useCallback,
	useEffect,
	useMemo,
	useRef,
	useState,
	type ReactNode
} from 'react'
import {
	StyleSheet,
	TouchableOpacity,
	View,
	PanResponder,
	Keyboard,
	Linking
} from 'react-native'
import Animated, {
	useSharedValue,
	useAnimatedStyle,
	interpolate,
	withTiming,
	Easing,
	runOnJS
} from 'react-native-reanimated'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import BottomSheet from '@gorhom/bottom-sheet'
import {
	ActiveDot,
	CloseIcon,
	MobileViewIcon,
	WebViewIcon,
	FabButton
} from './components'
import { LauncherState } from './utils/hooks/useLauncherState'
import { defineStyles } from '@/utils'
import { colors, useTheme } from '@/theme'
import { LiquidGlassView } from '@/components'
import { useCurrentOrganization } from '@/utils/hooks'
import { ExpoSpeechRecognitionModule } from 'expo-speech-recognition'
import { KeyboardStickyView } from 'react-native-keyboard-controller'
import {
	chatEmitter,
	ChatEvents,
	closeChatEmitter,
	CloseChatEvents,
	errorFixEmitter,
	ErrorFixEvents,
	modeChangeEmitter,
	ModeChangeEvents
} from '@/utils/emitter'
import { Link, Code, ArrowUpRight } from 'lucide-react-native'
import * as Clipboard from 'expo-clipboard'
import { toast } from '@/utils/toast'
import { DEFAULT_ANYTHING_WEB_URL, EXPO_GO_APP_STORE_URL } from '@/constants'
import Constants from 'expo-constants'
import { gte } from 'semver'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'
import { router } from 'expo-router'

const WITH_CODE_EDITOR =
	Constants.expoConfig?.version && gte(Constants.expoConfig.version, '1.0.6')
const WITH_LIQUID_GLASS = false

export const LauncherMenu = ({
	devServerHost,
	projectGroupId,
	children,
	state,
	switchToMobile,
	switchToWeb
}: {
	devServerHost: string | null
	projectGroupId: string
	children: ReactNode
	state: LauncherState
	switchToMobile: () => void
	switchToWeb: () => void
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const [speechPermission, setSpeechPermission] = useState<boolean | null>(null)
	const [_isCodeEditorVisible, setIsCodeEditorVisible] = useState(false)
	const { currentOrganization } = useCurrentOrganization()
	useEffect(() => {
		ExpoSpeechRecognitionModule.getPermissionsAsync().then((permission) => {
			setSpeechPermission(
				permission.status === 'granted' || permission.status === 'undetermined'
			)
		})
	}, [])
	const mobileCodeEditorEnabled = useBoolVariation(
		'mobile-code-editor-enabled',
		false
	)

	const bottomSheetRef = useRef<BottomSheet>(null)
	const menuProgress = useSharedValue(0)
	const [showFab, setShowFab] = useState(true)

	const anythingWebUrl: string =
		process.env.EXPO_PUBLIC_ANYTHING_WEB_URL ?? DEFAULT_ANYTHING_WEB_URL

	const hideMenuOffset = -(44 + 36 + insets.top + 10)

	const copyBuildLink = useCallback(() => {
		if (!projectGroupId) {
			toast.show({
				message: 'Something went wrong...',
				variant: 'error'
			})
			return
		}
		const url = new URL(`build/${projectGroupId}`, anythingWebUrl).toString()
		Clipboard.setStringAsync(url)
		toast.show({
			message: 'Build link copied!',
			variant: 'success'
		})
	}, [])

	const exitApp = useCallback(() => {
		router.back()
		// AnythingLauncherModule?.reset()
	}, [])

	const openExpoGo = useCallback(async () => {
		if (!devServerHost) {
			return
		}

		const url = `exp://${devServerHost}`
		const canOpen = await Linking.canOpenURL(url)

		if (!canOpen) {
			Linking.openURL(EXPO_GO_APP_STORE_URL)
			return
		}

		Linking.openURL(url)
	}, [devServerHost])

	const menuAnimatedStyle = useAnimatedStyle(() => {
		const translateY = interpolate(
			menuProgress.value,
			[0, 1],
			[hideMenuOffset, 0]
		)

		return {
			transform: [{ translateY }]
		}
	}, [hideMenuOffset])

	const overLayAnimatedStyle = useAnimatedStyle(() => {
		return {
			opacity: interpolate(menuProgress.value, [0, 1], [0, 0.2]),
			backgroundColor: 'black'
		}
	}, [menuProgress])

	const appPointerEvents = useAnimatedStyle(() => {
		return {
			pointerEvents: menuProgress.value === 1 ? 'box-only' : 'auto'
		}
	}, [menuProgress])

	const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

	const panResponder = useMemo(
		() =>
			PanResponder.create({
				onStartShouldSetPanResponder: (evt, gestureState) => {
					if (menuProgress.value === 1) {
						menuProgress.value = withTiming(
							0,
							{
								duration: 300,
								easing: Easing.ease
							},
							() => {
								runOnJS(setShowFab)(true)
							}
						)
						bottomSheetRef.current?.close()
						if (longPressTimer.current) {
							clearTimeout(longPressTimer.current)
							longPressTimer.current = null
						}
						return false
					}
					if (gestureState.numberActiveTouches === 2) {
						longPressTimer.current = setTimeout(() => {
							runOnJS(setShowFab)(false)
							menuProgress.value = withTiming(1, {
								duration: 300,
								easing: Easing.ease
							})
							bottomSheetRef.current?.expand()
							longPressTimer.current = null
						}, 500)
						return true
					}
					return false
				},
				onPanResponderEnd: (evt, gestureState) => {
					if (longPressTimer.current) {
						clearTimeout(longPressTimer.current)
						longPressTimer.current = null
					}
				}
			}),
		[]
	)

	useEffect(() => {
		const handleStreamingDone = () => {
			menuProgress.value = withTiming(
				0,
				{
					duration: 300,
					easing: Easing.ease
				},
				() => {
					runOnJS(setShowFab)(true)
				}
			)
			bottomSheetRef.current?.close()
		}

		const handleErrorFix = () => {
			if (menuProgress.value !== 1) {
				setShowFab(false)
				menuProgress.value = withTiming(1, {
					duration: 300,
					easing: Easing.ease
				})
				bottomSheetRef.current?.expand()
			}
		}

		const handleModeChange = ({ mode }: { mode: 'web' | 'mobile' }) => {
			if (mode === 'mobile') {
				switchToMobile()
			} else {
				switchToWeb()
			}
		}

		modeChangeEmitter.on(ModeChangeEvents.MODE_CHANGE, handleModeChange)
		chatEmitter.on(ChatEvents.STREAMING_DONE, handleStreamingDone)
		closeChatEmitter.on(CloseChatEvents.CLOSE_CHAT, handleDismiss)
		errorFixEmitter.on(ErrorFixEvents.ERROR_FIX_SUBMITTED, handleErrorFix)

		return () => {
			modeChangeEmitter.off(ModeChangeEvents.MODE_CHANGE, handleModeChange)
			chatEmitter.off(ChatEvents.STREAMING_DONE, handleStreamingDone)
			closeChatEmitter.off(CloseChatEvents.CLOSE_CHAT, handleDismiss)
			errorFixEmitter.off(ErrorFixEvents.ERROR_FIX_SUBMITTED, handleErrorFix)
		}
	}, [])

	const handleDismiss = useCallback(() => {
		bottomSheetRef.current?.close()
		menuProgress.value = withTiming(0, {
			duration: 300,
			easing: Easing.ease
		})
		setShowFab(true)
		Keyboard.dismiss()
	}, [bottomSheetRef, menuProgress])

	if (state.isLoading || speechPermission === null || !currentOrganization) {
		return null
	}

	return (
		<>
			<View style={styles.container} pointerEvents="box-none">
				<Animated.View
					style={styles.fill}
					pointerEvents="box-none"
					{...panResponder.panHandlers}
				>
					<Animated.View style={[styles.fillContent, appPointerEvents]}>
						{children}
					</Animated.View>
					<Animated.View
						style={[StyleSheet.absoluteFill, overLayAnimatedStyle]}
						pointerEvents={showFab ? 'none' : 'box-only'}
					/>
					<Animated.View
						style={[StyleSheet.absoluteFill, overLayAnimatedStyle]}
						pointerEvents="box-none"
					/>
				</Animated.View>
				<Animated.View
					style={[styles.menuContainer, menuAnimatedStyle]}
					pointerEvents="box-none"
				>
					<LiquidGlassView
						disabled={!WITH_LIQUID_GLASS}
						glassEffectStyle="clear"
						style={[
							menuStyles.menuContainerStyle,
							{
								marginTop: 12,
								padding: 0,
								margin: 10,
								backgroundColor: WITH_LIQUID_GLASS
									? 'transparent'
									: colors[theme].background
							}
						]}
					>
						<LiquidGlassView
							disabled={!WITH_LIQUID_GLASS}
							glassEffectStyle="clear"
							style={menuStyles.menuContainerStyle}
						>
							<View style={menuStyles.menuHeader}>
								<View style={menuStyles.leftSection}>
									<TouchableOpacity
										onPress={switchToMobile}
										style={menuStyles.button}
									>
										<MobileViewIcon
											color={
												state.mode === 'web'
													? colors[theme].gray[700]
													: colors[theme].gray[900]
											}
										/>
										{state.mode === 'mobile' && (
											<ActiveDot color={colors[theme].gray[900]} />
										)}
									</TouchableOpacity>
									<TouchableOpacity
										onPress={switchToWeb}
										style={menuStyles.button}
									>
										<WebViewIcon
											color={
												state.mode === 'web'
													? colors[theme].gray[900]
													: colors[theme].gray[700]
											}
										/>
										{state.mode === 'web' && (
											<ActiveDot color={colors[theme].gray[900]} />
										)}
									</TouchableOpacity>
								</View>
								<View style={menuStyles.buttonContainer}>
									{!!devServerHost && (
										<TouchableOpacity onPress={openExpoGo}>
											<ArrowUpRight size={18} color={colors[theme].gray[900]} />
										</TouchableOpacity>
									)}
									{WITH_CODE_EDITOR && mobileCodeEditorEnabled && (
										<TouchableOpacity
											onPress={() => setIsCodeEditorVisible(true)}
											style={menuStyles.button}
										>
											<Code size={18} color={colors[theme].gray[900]} />
										</TouchableOpacity>
									)}
									<TouchableOpacity
										onPress={copyBuildLink}
										style={menuStyles.button}
									>
										<Link size={18} color={colors[theme].gray[900]} />
									</TouchableOpacity>
									{/* <TouchableOpacity
										onPress={reloadApp}
										style={menuStyles.button}
									>
										<RefreshIcon color={colors[theme].gray[900]} />
									</TouchableOpacity> */}
									<TouchableOpacity onPress={exitApp} style={menuStyles.button}>
										<CloseIcon color={colors[theme].gray[900]} />
									</TouchableOpacity>
								</View>
							</View>
						</LiquidGlassView>
					</LiquidGlassView>
				</Animated.View>
				{/* <InstructionsOverlay
					showTint={state.showTint}
					width={width}
					height={height}
				/> */}
			</View>
			<KeyboardStickyView
				offset={{ closed: 0, opened: 20 }}
				style={styles.fabStickyContainer}
				pointerEvents="box-none"
			>
				<FabButton
					visible={showFab}
					onPress={() => {
						setShowFab(false)
						menuProgress.value = withTiming(1, {
							duration: 300,
							easing: Easing.ease
						})
						bottomSheetRef.current?.expand()
					}}
				/>
			</KeyboardStickyView>
			{/* <BottomSheet
				ref={bottomSheetRef}
				index={-1}
				snapPoints={[height - 200]}
				handleStyle={{ display: 'none' }}
				enablePanDownToClose
				enableOverDrag={false}
				onAnimate={(fromIndex, toIndex) => {
					if (toIndex === -1) {
						Keyboard.dismiss()
					}
					if (fromIndex === 0 && toIndex === -1) {
						menuProgress.value = withTiming(
							0,
							{
								duration: 300,
								easing: Easing.ease
							},
							() => {
								runOnJS(setShowFab)(true)
							}
						)
					}
				}}
				backgroundStyle={{
					backgroundColor: 'transparent'
				}}
			>
				<BottomSheetView
					style={{
						flex: 1,
						height: height - 200,
						borderTopEndRadius: 40,
						marginHorizontal: 10,
						marginBottom: 20
					}}
				>
					<ProjectScreen
						projectGroupId={projectGroupId}
						organizationId={currentOrganization.id}
						withLiquidGlass={WITH_LIQUID_GLASS}
						isLauncher={true}
						canUseMAX={currentOrganization.canUseMax}
					/>
				</BottomSheetView>
			</BottomSheet>
			{WITH_CODE_EDITOR && mobileCodeEditorEnabled && (
				<Modal
					visible={isCodeEditorVisible}
					onRequestClose={() => setIsCodeEditorVisible(false)}
					allowSwipeDismissal
					animationType="slide"
					presentationStyle="fullScreen"
					statusBarTranslucent
					backdropColor={colors[theme].gray[25]}
				>
					<CodeEditorScreen onClose={() => setIsCodeEditorVisible(false)} />
				</Modal>
			)} */}
		</>
	)
}

const styles = defineStyles({
	container: {
		flex: 1
	},
	fabStickyContainer: {
		position: 'absolute',
		left: 0,
		right: 0,
		bottom: 0
	},
	fillContent: {
		flex: 1,
		borderRadius: 16,
		overflow: 'hidden'
	},
	fill: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0
	},
	menuContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		zIndex: 1000
	}
})

const menuStyles = defineStyles({
	menuContainerStyle: {
		borderRadius: 40,
		margin: 1,
		overflow: 'hidden'
	},
	menuHeader: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
		paddingHorizontal: 20,
		paddingVertical: 18
	},
	buttonContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 28
	},
	button: {
		width: 18,
		height: 18,
		justifyContent: 'center',
		alignItems: 'center'
	},
	leftSection: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 28,
		flex: 1
	}
})
